// 黄金矿工钩子状态机

type HookState = 'IDLE' | 'SWINGING' | 'LAUNCHING' | 'RETRACTING' | 'GRABBING';

class HookStateMachine {
  private currentState: HookState;
  private prevState: HookState | null;

  constructor() {
    this.currentState = 'IDLE';
    this.prevState = null;
  }

  // 获取当前状态
  getCurrentState(): HookState {
    return this.currentState;
  }

  // 切换状态
  setState(newState: HookState): void {
    if (this.currentState !== newState) {
      this.onExit(this.currentState);
      this.prevState = this.currentState;
      this.currentState = newState;
      this.onEnter(newState);
    }
  }

  // 状态进入逻辑
  private onEnter(state: HookState): void {
    switch (state) {
      case 'IDLE':
        console.log('钩子处于待命状态，等待玩家操作');
        break;
      case 'SWINGING':
        console.log('钩子开始摆动，准备发射');
        break;
      case 'LAUNCHING':
        console.log('钩子发射，向目标方向移动');
        break;
      case 'RETRACTING':
        console.log('钩子开始回收，返回原点');
        break;
      case 'GRABBING':
        console.log('钩子抓取中，判定是否成功');
        break;
    }
  }

  // 状态退出逻辑
  private onExit(state: HookState): void {
    switch (state) {
      case 'IDLE':
        console.log('离开待命状态');
        break;
      case 'SWINGING':
        console.log('结束摆动状态');
        break;
      case 'LAUNCHING':
        console.log('发射过程结束');
        break;
      case 'RETRACTING':
        console.log('回收过程结束');
        break;
      case 'GRABBING':
        console.log('抓取过程结束');
        break;
    }
  }

  // 状态转换方法
  idle(): void {
    this.setState('IDLE');
  }

  swing(): void {
    if (this.currentState === 'IDLE') {
      this.setState('SWINGING');
    } else {
      console.warn(`无法从${this.currentState}状态切换到摆动状态`);
    }
  }

  launch(): void {
    if (this.currentState === 'SWINGING') {
      this.setState('LAUNCHING');
    } else {
      console.warn(`无法从${this.currentState}状态发射钩子`);
    }
  }

  retract(): void {
    if (['LAUNCHING', 'GRABBING'].includes(this.currentState)) {
      this.setState('RETRACTING');
    } else {
      console.warn(`无法从${this.currentState}状态回收钩子`);
    }
  }

  grab(): void {
    if (this.currentState === 'LAUNCHING') {
      this.setState('GRABBING');
    } else {
      console.warn(`无法从${this.currentState}状态进入抓取状态`);
    }
  }

  // 边界情况处理
  handleBoundaryCollision(): void {
    if (this.currentState === 'LAUNCHING') {
      // 如果撞击到边界，则开始回收
      console.log('钩子撞击边界，开始回收');
      this.retract();
    }
  }

  handleGrabResult(success: boolean): void {
    if (this.currentState === 'GRABBING') {
      if (success) {
        console.log('抓取成功，开始回收');
        this.retract();
      } else {
        console.log('抓取失败，开始回收');
        this.retract();
      }
    }
  }

  // 重置状态机
  reset(): void {
    this.setState('IDLE');
  }
}

// 使用示例
const hookSM = new HookStateMachine();
hookSM.idle();
hookSM.swing();
hookSM.launch();
hookSM.grab();
hookSM.handleGrabResult(true);
hookSM.retract();
hookSM.idle();

